MOD = 10**9 + 7

def powmod(a, x):
    if x == 0:
        return 1
    if x % 2 == 0:
        return powmod(a * a % MOD, x // 2)
    return a * powmod(a, x - 1) % MOD

def main():
    import sys
    k, va, vb = map(int, sys.stdin.readline().split())

    den = powmod(va + vb, MOD - 2)
